CREATE TABLE purchase_posts (id BIGINT AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, content TEXT NOT NULL, desired_price DECIMAL(15,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_purchase_buyer FOREIGN KEY (buyer_id) REFERENCES users(id));
CREATE TABLE purchase_post_images (id BIGINT AUTO_INCREMENT PRIMARY KEY, purchase_post_id BIGINT NOT NULL, object_key VARCHAR(255) NOT NULL, sort_order INT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_purchase_image FOREIGN KEY (purchase_post_id) REFERENCES purchase_posts(id));
